import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.I6s8z2kk.js";const y=JSON.parse('{"title":"Analytics","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/analytics.md","filePath":"dev/domain/analytics.md"}'),d={name:"dev/domain/analytics.md"};function i(r,e,c,s,l,m){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h1><p>The <strong>Analytics</strong> module serves dashboards from <strong>rollups</strong> built by <code>analytics:build</code> (daily at 00:30, <code>onOneServer</code>).</p><h2 id="admin-analytics" tabindex="-1">Admin analytics <a class="header-anchor" href="#admin-analytics" aria-label="Permalink to &quot;Admin analytics&quot;">​</a></h2><p>Requires <code>analytics.view</code>. Sections (<code>AnalyticsSection</code>): overview, revenue, bookings, payments, clients, centers, promotions, subscriptions and engagement.</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Section</th></tr></thead><tbody><tr><td><code>admin/analytics/overview</code></td><td>Overview</td></tr><tr><td><code>admin/analytics/revenue</code></td><td>Revenue</td></tr><tr><td><code>admin/analytics/bookings</code></td><td>Bookings</td></tr><tr><td><code>admin/analytics/payments</code></td><td>Payments</td></tr><tr><td><code>admin/analytics/clients</code></td><td>Clients</td></tr><tr><td><code>admin/analytics/centers</code></td><td>Centers</td></tr><tr><td><code>admin/analytics/promotions</code></td><td>Promotions</td></tr><tr><td><code>admin/analytics/subscriptions</code></td><td>Subscriptions</td></tr><tr><td><code>admin/analytics/engagement</code></td><td>Client engagement</td></tr><tr><td><code>admin/analytics/home-content</code></td><td><a href="./homepage">Homepage</a> content events</td></tr><tr><td><code>admin/analytics/export</code></td><td>Export</td></tr></tbody></table><h3 id="financial-baseline-corrections" tabindex="-1">Financial baseline corrections <a class="header-anchor" href="#financial-baseline-corrections" aria-label="Permalink to &quot;Financial baseline corrections&quot;">​</a></h3><p><code>BuildDailyCenterStats</code> adds each <strong>confirmed</strong> <a href="./settlements#financial-baselines">financial baseline</a> to the day of its <code>cutoff_at</code>: <code>net_fee</code>, <code>gmv</code> and <code>refunds</code> move by <code>target - migrated</code> for every target finance gave. The whole correction lands on that one day (it can be negative), so totals over a range that includes it match finance. <code>baseline_adjustment</code> ledger entries are not revenue and are ignored. <code>RebuildBaselineCutoffDay</code> rebuilds the cutoff day when a baseline is confirmed, unless it is today.</p><h2 id="center-analytics" tabindex="-1">Center analytics <a class="header-anchor" href="#center-analytics" aria-label="Permalink to &quot;Center analytics&quot;">​</a></h2><p><code>GET centers/{center}/analytics</code> (permission <code>analytics.view</code>) shows the center&#39;s own numbers.</p><ul><li>Revenue counts only <strong>Confirmed</strong> and <strong>Completed</strong> purchases where the center is the merchant, compared with the previous period of the same length.</li><li>Analytics are <strong>center-wide</strong>; they are not narrowed by purchase visibility.</li></ul><h2 id="engagement" tabindex="-1">Engagement <a class="header-anchor" href="#engagement" aria-label="Permalink to &quot;Engagement&quot;">​</a></h2><p>Clients report engagement through <code>POST clients/engagement/events</code>. Events are aggregate-only: no personal data is stored.</p>',12)])])}const g=t(d,[["render",i]]);export{y as __pageData,g as default};
